package org.sleepwell.app;

import org.junit.Test;import static org.junit.Assert.*;import java.time.*;import java.util.*;

public final class RecordInsightsTest {
    final Instant now=Instant.parse("2026-10-26T18:00:00Z");final LocalDate end=LocalDate.of(2026,10,25);
    RecordEntry record(long id,int day,int minute,int duration,String...tags){long start=LocalDate.of(2026,10,day).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli()+minute*60000L;RecordDraft draft=new RecordDraft(start,start+duration*60000L);for(String tag:tags)draft.addTag(tag);return new RecordEntry(id,start,draft.end,null,"manual","local","UTC",0,0,draft,true,id,List.of());}
    RecordInsights inspect(List<RecordEntry> rows,List<GoalCommitment> goals){return new RecordInsights(rows,goals,end,7,0,now);}
    GoalCommitment goal(int target){return new GoalCommitment("e354e6cb-43d5-48bc-9a32-6eb96a198bef","duration",target,LocalDate.of(2026,10,19),14,"UTC",0,"",null);}
    @Test public void missingDatesRemainUnknownAndNeverEnterTheAverage(){RecordInsights empty=inspect(List.of(),List.of());assertNull(empty.average);assertEquals(7,empty.missing);assertTrue(empty.days.stream().allMatch(d->d.duration==null));RecordInsights result=inspect(List.of(record(1,20,0,420),record(2,23,0,480)),List.of());assertEquals(2,result.observed);assertEquals(5,result.missing);assertEquals(450*60000L,(long)result.average);assertEquals(450*60000L,(long)result.median);assertNull(result.days.get(0).duration);}
    @Test public void overlapsAndMarkedAwakeTimeAreNotCountedTwice(){RecordEntry a=record(1,20,0,480),b=record(2,20,240,360);a.edit.awake.add(new RecordIntervals.Span(a.edit.start,a.edit.start+60*60000L));RecordInsights result=inspect(List.of(a,b),List.of());assertEquals(1,result.observed);assertEquals(540*60000L,(long)result.average);assertEquals(2,result.manual);}
    @Test public void currentPlanCannotRetrofitAnAbsentHistoricalGoal(){RecordInsights none=inspect(List.of(record(1,20,0,420)),List.of());assertFalse(none.goal.hasDates());assertEquals(0,none.goal.observed);assertNull(none.days.get(1).balance);RecordInsights saved=inspect(List.of(record(1,20,0,420)),List.of(goal(480)));assertEquals(-60*60000L,saved.goal.balance);assertEquals(1,saved.goal.observed);assertEquals(6,saved.goal.unknown);assertEquals(-60*60000L,(long)saved.days.get(1).balance);}
    @Test public void unreadableGoalsDoNotSuppressOtherStatistics(){RecordInsights result=inspect(List.of(record(1,20,0,420)),null);assertFalse(result.goalsAvailable);assertEquals(1,result.observed);assertEquals(420*60000L,(long)result.average);assertTrue(result.days.stream().allMatch(d->d.balance==null));}
    @Test public void zeroRemainingCoverageIsKnownButUnobservedDatesAreNotZero(){RecordEntry a=record(1,20,0,60);a.edit.awake.add(new RecordIntervals.Span(a.edit.start,a.edit.end));RecordInsights result=inspect(List.of(a),List.of());assertEquals(1,result.observed);assertEquals(0,(long)result.average);assertNull(result.days.get(0).duration);assertEquals(0,(long)result.days.get(1).duration);}
    @Test public void circularStartRangeHandlesMidnightAndExcludesNaps(){RecordEntry a=record(1,19,1430,480),b=record(2,21,10,480),nap=record(3,24,800,240,"nap");RecordInsights result=inspect(List.of(a,b,nap),List.of());assertEquals(2,result.mainPeriods);assertEquals(20,result.startRange,.001);assertEquals(3,result.observed);assertNull(inspect(List.of(a),List.of()).startRange);}
    @Test public void tagComparisonsRequireBothGroupsAndNeverInferCausation(){List<RecordEntry> rows=new ArrayList<>();for(int n=0;n<3;n++)rows.add(record(n+1,19+n,0,420,"Coffee"));for(int n=0;n<3;n++)rows.add(record(n+4,22+n,0,480));RecordInsights result=inspect(rows,List.of());assertEquals(1,result.associations.size());RecordInsights.Association a=result.associations.get(0);assertEquals("Coffee",a.tag);assertEquals(3,a.with);assertEquals(3,a.without);assertEquals(-60*60000L,a.difference);rows.remove(0);assertTrue(inspect(rows,List.of()).associations.isEmpty());}
    @Test public void futureOpenAndInvalidPeriodsCannotManufactureEvidence(){RecordEntry future=record(1,27,0,480),valid=record(2,20,0,480);RecordEntry open=new RecordEntry(3,valid.rawStart,0,null,"tracked","local","UTC",0,0,valid.edit,false,0,List.of());RecordInsights result=inspect(List.of(future,open),List.of());assertEquals(0,result.observed);assertEquals(2,result.excluded);assertNull(result.startRange);}
    @Test public void duplicatePhysicalIntervalAcrossZonesDoesNotCreateASecondObservedDay(){RecordEntry utc=record(1,20,0,480),duplicate=new RecordEntry(2,utc.rawStart,utc.rawEnd,null,"manual","imported","Pacific/Honolulu",0,0,utc.edit,false,0,List.of());RecordInsights result=inspect(List.of(utc,duplicate),List.of());assertEquals(1,result.observed);assertEquals(480*60000L,(long)result.average);}
    @Test public void actualRecordZoneAndCutoffDefineCoverageWithoutChangingElapsedDuration(){RecordEntry a=record(1,20,0,480);RecordInsights midnight=new RecordInsights(List.of(a),List.of(),end,7,0,now),noon=new RecordInsights(List.of(a),List.of(),end,7,720,now);assertEquals(midnight.average,noon.average);assertEquals(480*60000L,(long)midnight.days.get(1).duration);assertEquals(480*60000L,(long)noon.days.get(0).duration);}
    @Test public void stoppedGoalsAndCurrentOpenDatesDoNotBecomeFalseDeficits(){GoalCommitment stopped=goal(480).stop(LocalDate.of(2026,10,20));RecordInsights result=inspect(List.of(record(1,20,0,420),record(2,23,0,480)),List.of(stopped));assertEquals(1,result.goal.observed);assertEquals(1,result.goal.unknown);assertEquals(-60*60000L,result.goal.balance);assertNull(result.days.get(4).balance);}
    @Test public void unsupportedWindowAndCutoffRejectWithoutMutation(){assertThrows(IllegalArgumentException.class,()->new RecordInsights(List.of(),List.of(),end,365,0,now));assertThrows(IllegalArgumentException.class,()->new RecordInsights(List.of(),List.of(),end,7,-1,now));assertThrows(IllegalArgumentException.class,()->new RecordInsights(List.of(),List.of(),end,7,1440,now));}
}
